from abc import ABC, abstractmethod


class Observer(ABC):
    @abstractmethod
    def update(self, event: str, data: dict):
        pass


class Subject:
    def __init__(self):
        self._observers: dict[str, list[Observer]] = {}

    def attach(self, event: str, observer: Observer):
        self._observers.setdefault(event, []).append(observer)

    def detach(self, event: str, observer: Observer):
        self._observers.get(event, []).remove(observer)

    def notify(self, event: str, data: dict):
        for observer in self._observers.get(event, []):
            observer.update(event, data)


class FilterObserver(Observer):
    def __init__(self, filter_fn):
        self.filter_fn = filter_fn
        self.accepted = True

    def update(self, event: str, data: dict):
        if event == "before_process":
            self.accepted = self.filter_fn(data["item"])


class TransformObserver(Observer):
    def __init__(self, transform_fn):
        self.transform_fn = transform_fn

    def update(self, event: str, data: dict):
        if event == "after_filter":
            data["item"] = self.transform_fn(data["item"])


class DataProcessor(Subject):
    def __init__(self):
        super().__init__()
        self._filters: list[FilterObserver] = []

    def add_filter(self, filter_fn) -> FilterObserver:
        obs = FilterObserver(filter_fn)
        self._filters.append(obs)
        self.attach("before_process", obs)
        return obs

    def add_transform(self, transform_fn) -> TransformObserver:
        obs = TransformObserver(transform_fn)
        self.attach("after_filter", obs)
        return obs

    def process(self, data):
        result = []
        for item in data:
            ctx = {"item": item}

            self.notify("before_process", ctx)

            if not all(f.accepted for f in self._filters):
                continue

            self.notify("after_filter", ctx)

            result.append(ctx["item"])
        return result


# Usage
if __name__ == "__main__":
    processor = DataProcessor()
    processor.add_filter(lambda x: x > 0)
    processor.add_transform(lambda x: x * 2)

    print(processor.process([-1, 0, 1, 2, 3]))  # [2, 4, 6]

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable


class Observer(ABC):
    @abstractmethod
    def update(self, event: str, data: dict[str, Any]) -> None:
        pass


class Subject:
    def __init__(self) -> None:
        self._observers: dict[str, list[Observer]] = {}

    def attach(self, event: str, observer: Observer) -> None:
        self._observers.setdefault(event, []).append(observer)

    def detach(self, event: str, observer: Observer) -> None:
        self._observers.get(event, []).remove(observer)

    def notify(self, event: str, data: dict[str, Any]) -> None:
        for observer in self._observers.get(event, []):
            observer.update(event, data)


class FilterObserver(Observer):
    def __init__(self, filter_fn: Callable[[Any], bool]) -> None:
        self._filter_fn = filter_fn
        self.accepted = True

    def update(self, event: str, data: dict[str, Any]) -> None:
        if event == "before_process":
            self.accepted = self._filter_fn(data["item"])


class TransformObserver(Observer):
    def __init__(self, transform_fn: Callable[[Any], Any]) -> None:
        self._transform_fn = transform_fn

    def update(self, event: str, data: dict[str, Any]) -> None:
        if event == "after_filter":
            data["item"] = self._transform_fn(data["item"])


class DataProcessor(Subject):
    def __init__(self) -> None:
        super().__init__()
        self._filters: list[FilterObserver] = []

    def add_filter(self, filter_fn: Callable[[Any], bool]) -> FilterObserver:
        obs = FilterObserver(filter_fn)
        self._filters.append(obs)
        self.attach("before_process", obs)
        return obs

    def add_transform(self, transform_fn: Callable[[Any], Any]) -> TransformObserver:
        obs = TransformObserver(transform_fn)
        self.attach("after_filter", obs)
        return obs

    def process(self, data: list[Any]) -> list[Any]:
        result = []
        for item in data:
            ctx: dict[str, Any] = {"item": item}

            self.notify("before_process", ctx)

            if not all(f.accepted for f in self._filters):
                continue

            self.notify("after_filter", ctx)

            result.append(ctx["item"])
        return result


if __name__ == "__main__":
    processor = DataProcessor()
    processor.add_filter(lambda x: x > 0)
    processor.add_transform(lambda x: x * 2)

    print(processor.process([-1, 0, 1, 2, 3]))  # [2, 4, 6]

